// Fonction pour obtenir une traduction
export const getHelpText = (lang, path) => {
  const keys = path.split('.');
  let value = helpTranslations[lang] || helpTranslations.fr;
  
  for (const key of keys) {
    value = value?.[key];
    if (!value) return path;
  }
  
  return value;
};
